// v28.xx (cw-cx-camera130), HIS PICK (2026-10-18, art survey a36 C): "30 percent closer". One default for both windows and every raid mode; a saved dial keeps its value.
var ZDEFAULT=1.3,ZT=ZDEFAULT,ZC=ZDEFAULT,zoomSaveT=0;
function loadZoom(){ ZT=ZC=clamp(P.zoom||ZDEFAULT,ZMIN,ZMAX); }

check:
{v:'VER',what:'camera defaults to 1.3, keeps saved zoom, and draws the HUD, map, extraction and partner arrows at that zoom (his a36 C)',
 run:function(){
   if(typeof loadZoom!=='function') return 'the boot camera still has no 1.3 default loader';
   if(!(window.__deploy&&window.__state&&window.__frame)) return 'missing camera fixture hooks';
   var bad=[], had=Object.prototype.hasOwnProperty.call(P,'zoom'), saved=P.zoom,
       oldZT=ZT, oldZC=ZC, oldSaveT=zoomSaveT,
       mx=mouse.x, my=mouse.y, oldText=hudText, words=[], phase='profile';
   function near(a,b,label,tol){ if(!isFinite(a)||Math.abs(a-b)>(tol||0.01)) bad.push(label+': '+a+' expected '+b); }
   try{
     __runPrep(); __topClear(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     delete P.zoom; loadZoom(); near(ZT,1.3,'fresh target'); near(ZC,1.3,'fresh eased camera');
     if(Object.prototype.hasOwnProperty.call(P,'zoom')) bad.push('loading the default wrote over the profile');
     [1,2.15].forEach(function(z){ P.zoom=z; loadZoom(); near(ZT,z,'saved target'); near(ZC,z,'saved eased camera'); near(P.zoom,z,'saved preference'); });
     hudText=function(s){ words.push(String(s)); return oldText.apply(this,arguments); };
     phase='deploy';
     __deploy({kit:['gun_carbine','bandage'],safe:null,mapIx:0,seed:4242});
     var g=__state(), p=g&&g.player;
     if(!p||g.over) return 'no live raid for camera check';
     g.ents.length=0; p.iv=99; p.ads=false; g.adsZ=1; g.sprinting=false;
     g.mapFirst=0; g.paused=false; g.mapOpen=false; g.bagOpen=false;
     keys={}; mouse.down=false; mouse.x=W/2; mouse.y=H/2;
     p.x=WORLD_W/2; p.y=WORLD_H/2;
     g.anchX=p.x; g.anchY=p.y; g.leanSX=0; g.leanSY=0;
     delete P.zoom; loadZoom(); words=[]; CFG.minimap=1;
     g.beaconT=10; phase='raid draw'; __frame(0);
     var z=ZOOM(), s=w2s(p.x,0,p.y), mw=mouseWorld(), back=w2s(mw.x,0,mw.y);
     near(z,1.3*hudRes(),'camera projection');
     near(s.x,W/2,'pillager x',3); near(s.y,H*0.54,'pillager y',3);
     near(back.x,mouse.x,'pointer x',3); near(back.y,mouse.y,'pointer y',3);
     if(!MMAP.box||MMAP.ops<4) bad.push('minimap did not draw');
     if(!words.some(function(t){ return /extract.*inbound/i.test(t); })) bad.push('extraction HUD did not draw');
     var az=g.active, mark=w2s(az.x,0,az.y);
     near(mark.x,(az.x-VX)*z,'extraction marker x'); near(mark.y,(az.y-VY)*z,'extraction marker y');
     phase='partner arrows';
     var arrow=netMateArrow({x:p.x,y:p.y+H/z+100,seat:2,dn:0});
     if(!arrow||arrow.x<0||arrow.x>W||arrow.y<0||arrow.y>H) bad.push('off-screen partner arrow missing or outside the screen');
     if(netMateArrow({x:p.x,y:p.y,seat:2,dn:0})!==null) bad.push('on-screen partner has an edge arrow');
     phase='sector map';
     var mp=mapProj(), mm=mmSpan(), mapWords=0, fill=ctx.fillText;
     ctx.fillText=function(){ mapWords++; return fill.apply(this,arguments); };
     g.mapOpen=true;
     try{ drawMapOverlay(); }finally{ ctx.fillText=fill; g.mapOpen=false; }
     if(mapWords<3) bad.push('sector map did not draw its labels');
     setZoom(1,true); var wide=mapProj(); delete P.zoom; loadZoom();
     near(wide.sc,mp.sc,'sector map independent scale'); near(mmSpan(),mm,'minimap independent span');
     return bad.length?bad.join('; '):null;
   } catch(err){
     return 'camera check at '+phase+': '+String(err&&err.message||err);
   } finally {
     hudText=oldText;
     try{ __endRaid('abandon'); }catch(_e){}
     if(had) P.zoom=saved; else delete P.zoom;
     ZT=oldZT; ZC=oldZC; zoomSaveT=oldSaveT;
     mouse.x=mx; mouse.y=my;
     __topClear();
   }
 }},
